function ToolOptions({
  onChange,
  tool,
  values,
}: {
  onChange: (name: string, value: unknown) => void
  tool: ChatTool
  values: Record<string, unknown>
}) {
  const tt = useToolText()

  return (
    <FieldGroup>
      {chatTools[tool].fields.map((field) => {
        const controlId = `tool-${tool}-${field.name}`
        const value = values[field.name]

        if (field.kind === "switch") {
          return (
            <Field key={field.name} orientation="horizontal">
              <Switch
                checked={Boolean(value)}
                id={controlId}
                onCheckedChange={(checked) => onChange(field.name, checked)}
              />
              <FieldLabel htmlFor={controlId}>{tt(field.labelKey)}</FieldLabel>
            </Field>
          )
        }

        if (field.kind === "toggles") {
          const selected = Array.isArray(value) ? (value as string[]) : []
          return (
            <Field key={field.name}>
              <FieldLabel>{tt(field.labelKey)}</FieldLabel>
              <ToggleGroup
                className="flex-wrap justify-start"
                onValueChange={(next) => onChange(field.name, next)}
                type="multiple"
                value={selected}
                variant="outline"
              >
                {field.options.map((option) => {
                  return (
                    <ToggleGroupItem key={option.value} value={option.value}>
                      {tt(option.labelKey)}
                    </ToggleGroupItem>
                  )
                })}
              </ToggleGroup>
            </Field>
          )
        }

        if (field.kind === "select") {
          return (
            <Field key={field.name}>
              <FieldLabel htmlFor={controlId}>{tt(field.labelKey)}</FieldLabel>
              <Select
                onValueChange={(next) => onChange(field.name, next)}
                value={String(value ?? "")}
              >
                <SelectTrigger className="w-full" id={controlId}>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectGroup>
                    {field.options.map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {tt(option.labelKey)}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
            </Field>
          )
        }

        return (
          <Field key={field.name}>
            <FieldLabel htmlFor={controlId}>{tt(field.labelKey)}</FieldLabel>
            <Input
              id={controlId}
              max={field.kind === "number" ? field.max : undefined}
              min={field.kind === "number" ? field.min : undefined}
              onChange={(event) =>
                onChange(
                  field.name,
                  field.kind === "number"
                    ? Number(event.target.value) || field.min
                    : event.target.value
                )
              }
              placeholder={
                field.kind === "text" && field.placeholderKey
                  ? tt(field.placeholderKey)
                  : undefined
              }
              type={field.kind === "number" ? "number" : "text"}
              value={String(value ?? "")}
            />
          </Field>
        )
      })}
    </FieldGroup>
  )
}

