function toolDateValue(value: unknown) {
  if (typeof value !== "string" || !value) return undefined
  const parsed = new Date(`${value}T00:00:00`)
  return Number.isNaN(parsed.getTime()) ? undefined : parsed
}

function toolDateString(date: Date) {
  const month = String(date.getMonth() + 1).padStart(2, "0")
  const day = String(date.getDate()).padStart(2, "0")
  return `${date.getFullYear()}-${month}-${day}`
}

function InlineToolOptions({
  disabled,
  onChange,
  tool,
  values,
}: {
  disabled: boolean
  onChange: (name: string, value: unknown) => void
  tool: ChatTool
  values: Record<string, unknown>
}) {
  const t = useTranslations("aiStudio.chat")
  const tt = useToolText()
  const format = useFormatter()

  return (
    <>
      {chatTools[tool].fields.map((field) => {
        const controlId = `tool-${tool}-${field.name}`
        const value = values[field.name]

        if (field.kind === "switch") {
          return (
            <Toggle
              disabled={disabled}
              key={field.name}
              onPressedChange={(pressed) => onChange(field.name, pressed)}
              pressed={Boolean(value)}
              size="sm"
              variant="outline"
            >
              {tt(field.labelKey)}
            </Toggle>
          )
        }

        if (field.kind === "toggles") {
          const selected = Array.isArray(value) ? (value as string[]) : []
          return (
            <DropdownMenu key={field.name}>
              <DropdownMenuTrigger asChild>
                <PromptInputButton disabled={disabled}>
                  {selected.length
                    ? t("optionCount", {
                        count: selected.length,
                        label: tt(field.labelKey),
                      })
                    : tt(field.labelKey)}
                </PromptInputButton>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start">
                {field.options.map((option) => (
                  <DropdownMenuCheckboxItem
                    checked={selected.includes(option.value)}
                    key={option.value}
                    onCheckedChange={(checked) =>
                      onChange(
                        field.name,
                        checked
                          ? [...selected, option.value]
                          : selected.filter((item) => item !== option.value)
                      )
                    }
                    onSelect={(event) => event.preventDefault()}
                  >
                    {tt(option.labelKey)}
                  </DropdownMenuCheckboxItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          )
        }

        if (field.kind === "select") {
          return (
            <PromptInputSelect
              disabled={disabled}
              key={field.name}
              onValueChange={(next) => onChange(field.name, next)}
              value={String(value ?? "")}
            >
              <PromptInputSelectTrigger aria-label={tt(field.labelKey)}>
                <PromptInputSelectValue />
              </PromptInputSelectTrigger>
              <PromptInputSelectContent>
                {field.options.map((option) => (
                  <PromptInputSelectItem
                    key={option.value}
                    value={option.value}
                  >
                    {tt(option.labelKey)}
                  </PromptInputSelectItem>
                ))}
              </PromptInputSelectContent>
            </PromptInputSelect>
          )
        }

        if (field.kind === "date") {
          const selectedDate = toolDateValue(value)
          return (
            <Popover key={field.name}>
              <PopoverTrigger asChild>
                <PromptInputButton disabled={disabled}>
                  {selectedDate
                    ? t("optionValue", {
                        label: tt(field.labelKey),
                        value: format.dateTime(selectedDate, {
                          dateStyle: "medium",
                        }),
                      })
                    : tt(field.labelKey)}
                </PromptInputButton>
              </PopoverTrigger>
              <PopoverContent align="start" className="w-auto p-0">
                <Calendar
                  mode="single"
                  onSelect={(next) =>
                    onChange(field.name, next ? toolDateString(next) : "")
                  }
                  selected={selectedDate}
                />
              </PopoverContent>
            </Popover>
          )
        }

        const filled =
          field.kind === "number"
            ? typeof value === "number"
            : typeof value === "string" && value.trim() !== ""

        return (
          <Popover key={field.name}>
            <PopoverTrigger asChild>
              <PromptInputButton className="max-w-48" disabled={disabled}>
                <span className="truncate">
                  {filled
                    ? t("optionValue", {
                        label: tt(field.labelKey),
                        value:
                          field.kind === "number"
                            ? format.number(value as number)
                            : String(value),
                      })
                    : tt(field.labelKey)}
                </span>
              </PromptInputButton>
            </PopoverTrigger>
            <PopoverContent align="start" className="w-64">
              <Field>
                <FieldLabel htmlFor={controlId}>
                  {tt(field.labelKey)}
                </FieldLabel>
                <Input
                  id={controlId}
                  max={field.kind === "number" ? field.max : undefined}
                  min={field.kind === "number" ? field.min : undefined}
                  onChange={(event) =>
                    onChange(
                      field.name,
                      field.kind === "number"
                        ? Number(event.target.value) || field.min
                        : event.target.value
                    )
                  }
                  placeholder={
                    field.kind === "text" && field.placeholderKey
                      ? tt(field.placeholderKey)
                      : undefined
                  }
                  type={field.kind === "number" ? "number" : "text"}
                  value={String(value ?? "")}
                />
              </Field>
            </PopoverContent>
          </Popover>
        )
      })}
    </>
  )
}

