                        field.name,
                        checked
                          ? [...selected, option.value]
                          : selected.filter((item) => item !== option.value)
                      )
                    }
                    onSelect={(event) => event.preventDefault()}
                  >
                    {tt(option.labelKey)}
                  </DropdownMenuCheckboxItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          )
        }

        if (field.kind === "select") {
          return (
            <PromptInputSelect
              disabled={disabled}
              key={field.name}
              onValueChange={(next) => onChange(field.name, next)}
              value={String(value ?? "")}
            >
              <PromptInputSelectTrigger aria-label={tt(field.labelKey)}>
                <PromptInputSelectValue />
              </PromptInputSelectTrigger>
              <PromptInputSelectContent>
                {field.options.map((option) => (
                  <PromptInputSelectItem
                    key={option.value}
                    value={option.value}
                  >
                    {tt(option.labelKey)}
                  </PromptInputSelectItem>
                ))}
              </PromptInputSelectContent>
            </PromptInputSelect>
          )
        }

        if (field.kind === "date") {
          const selectedDate = toolDateValue(value)
          return (
            <Popover key={field.name}>
              <PopoverTrigger asChild>
                <PromptInputButton disabled={disabled}>
                  {selectedDate
                    ? t("optionValue", {
                        label: tt(field.labelKey),
                        value: format.dateTime(selectedDate, {
                          dateStyle: "medium",
                        }),
                      })
                    : tt(field.labelKey)}
                </PromptInputButton>
              </PopoverTrigger>
              <PopoverContent align="start" className="w-auto p-0">
                <Calendar
                  mode="single"
                  onSelect={(next) =>
                    onChange(field.name, next ? toolDateString(next) : "")
                  }
                  selected={selectedDate}
                />
              </PopoverContent>
            </Popover>
          )
        }

        const filled =
          field.kind === "number"
            ? typeof value === "number"
            : typeof value === "string" && value.trim() !== ""

        return (
          <Popover key={field.name}>
            <PopoverTrigger asChild>
              <PromptInputButton className="max-w-48" disabled={disabled}>
                <span className="truncate">
                  {filled
                    ? t("optionValue", {
                        label: tt(field.labelKey),
                        value:
                          field.kind === "number"
                            ? format.number(value as number)
                            : String(value),
                      })
                    : tt(field.labelKey)}
                </span>
              </PromptInputButton>
            </PopoverTrigger>
            <PopoverContent align="start" className="w-64">
              <Field>
                <FieldLabel htmlFor={controlId}>
                  {tt(field.labelKey)}
                </FieldLabel>
                <Input
                  id={controlId}
                  max={field.kind === "number" ? field.max : undefined}
                  min={field.kind === "number" ? field.min : undefined}
                  onChange={(event) =>
                    onChange(
                      field.name,
                      field.kind === "number"
                        ? Number(event.target.value) || field.min
                        : event.target.value
                    )
                  }
                  placeholder={
                    field.kind === "text" && field.placeholderKey
                      ? tt(field.placeholderKey)
                      : undefined
                  }
                  type={field.kind === "number" ? "number" : "text"}
                  value={String(value ?? "")}
                />
              </Field>
            </PopoverContent>
          </Popover>
        )
      })}
    </>
  )
}

