    if (job.name !== AI_REQUEST_JOB) return;
    const jobId = String(job.id ?? `ai-${job.data.aiRequestId}`);
    const [request] = await this.database.db
      .update(aiRequests)
      .set({
        status: 'processing',
        progress: 5,
        jobId,
        startedAt: sql`coalesce(${aiRequests.startedAt}, now())`,
        errorCode: null,
